import { expect, Locator, Page } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';

export class RanchPage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  // -- Navigation / List (/ranches) --
  get ranchesNavLink(): Locator {
    return this.page.getByRole('link', { name: 'Ranches' });
  }

  get createNewRanchButton(): Locator {
    return this.page.getByRole('button', { name: 'Create New Ranch' });
  }

  get searchRanchesInput(): Locator {
    return this.page.getByPlaceholder('Search ranches...');
  }

  get ranchesTable(): Locator {
    return this.page.getByRole('table');
  }

  ranchRow(ranchName: string): Locator {
    return this.page.getByRole('row', { name: new RegExp(ranchName, 'i') });
  }

  editRanchButton(ranchName: string): Locator {
    return this.ranchRow(ranchName).getByRole('button', { name: 'Edit' });
  }

  get loadingIndicator(): Locator {
    return this.page.getByRole('status').or(this.page.locator('[data-loading="true"], .skeleton, .spinner'));
  }

  get errorState(): Locator {
    return this.page.getByRole('alert');
  }

  // -- Wizard shell (common to all 5 steps) --
  get wizardHeading(): Locator {
    return this.page.getByRole('heading', { name: 'Create New Ranch' });
  }

  get stepIndicator(): Locator {
    return this.page.getByText(/Step \d of 5/);
  }

  stepLabel(stepName: string): Locator {
    return this.page.getByText(stepName, { exact: true });
  }

  get currentStepBadge(): Locator {
    return this.page.locator('[aria-current="step"]');
  }

  get nextButton(): Locator {
    return this.page.getByRole('button', { name: 'Next' });
  }

  get backButton(): Locator {
    return this.page.getByRole('button', { name: 'Back' });
  }

  get backToRanchesButton(): Locator {
    return this.page.getByRole('button', { name: 'Back to Ranches' });
  }

  mandatoryIndicatorFor(labelText: string): Locator {
    return this.page.locator(`text="${labelText}"`).locator('xpath=following-sibling::*[1]');
  }

  fieldValidationError(fieldLabel: string): Locator {
    return this.page
      .locator('div')
      .filter({ has: this.page.getByLabel(new RegExp(fieldLabel, 'i')) })
      .getByText(/required|invalid|must/i);
  }

  get successToast(): Locator {
    return this.page.locator('[role="status"], [data-sonner-toast], .toast').first();
  }

  // -- Step 1: Basic Information (live-confirmed) --
  get ranchNameInput(): Locator {
    return this.page.getByLabel('Ranch Name', { exact: false });
  }

  get fullAddressInput(): Locator {
    return this.page.getByLabel('Full Address', { exact: false });
  }

  get countyInput(): Locator {
    return this.page.getByLabel('County', { exact: false });
  }

  get countryCodeSelector(): Locator {
    return this.page.getByRole('combobox', { name: 'Country selector' });
  }

  // Confirmed live 2026-11-03: "Contact Phone" has no for/aria-labelledby association —
  // getByLabel does not resolve it. There is exactly one tel input on this wizard step.
  get contactPhoneInput(): Locator {
    return this.page.locator('input[type="tel"]');
  }

  get contactEmailInput(): Locator {
    return this.page.getByLabel('Contact Email', { exact: false });
  }

  // -- Step 2: Ranch Details (documented, see GAP note above) --
  get propertySizeInput(): Locator {
    return this.page.getByLabel(/Property Size/i);
  }

  get ranchDescriptionInput(): Locator {
    return this.page.getByLabel(/Ranch Description/i);
  }

  huntableAnimalOption(animalName: string): Locator {
    return this.page.getByRole('checkbox', { name: animalName }).or(this.page.getByRole('option', { name: animalName }));
  }

  get websiteUrlInput(): Locator {
    return this.page.getByLabel(/Website URL/i);
  }

  get addStandButton(): Locator {
    return this.page.getByRole('button', { name: /Add Stand/i });
  }

  get addAddonButton(): Locator {
    return this.page.getByRole('button', { name: /Add.?on/i });
  }

  // -- Step 3: Rooms (documented, see GAP note above) --
  get addRoomButton(): Locator {
    return this.page.getByRole('button', { name: /Add Room/i });
  }

  roomRow(roomName: string): Locator {
    return this.page.getByRole('row', { name: new RegExp(roomName, 'i') }).or(this.page.locator(`[data-room-name="${roomName}"]`));
  }

  roomNameInput(rowIndex = 0): Locator {
    return this.page.getByLabel(/Room Name/i).nth(rowIndex);
  }

  bedsStepperIncrement(rowIndex = 0): Locator {
    return this.page.getByRole('button', { name: /increment|increase beds|\+/i }).nth(rowIndex);
  }

  bedsStepperDecrement(rowIndex = 0): Locator {
    return this.page.getByRole('button', { name: /decrement|decrease beds|-/i }).nth(rowIndex);
  }

  bedsValue(rowIndex = 0): Locator {
    return this.page.getByLabel(/Beds/i).nth(rowIndex);
  }

  costPerNightInput(rowIndex = 0): Locator {
    return this.page.getByLabel(/Cost per Night/i).nth(rowIndex);
  }

  removeRoomButton(roomName: string): Locator {
    return this.roomRow(roomName).getByRole('button', { name: /remove|delete/i });
  }

  // -- Step 4: Initial Settings (documented, see GAP note above) --
  get turnoverDaysDropdown(): Locator {
    return this.page.getByLabel(/Turnover Days/i);
  }

  turnoverDaysOption(value: string): Locator {
    return this.page.getByRole('option', { name: value });
  }

  get waiverSigningDeadlineInput(): Locator {
    return this.page.getByLabel(/Waiver Signing Deadline/i);
  }

  get waiverExpirationInput(): Locator {
    return this.page.getByLabel(/Waiver Expiration/i);
  }

  get harvestReportEmailFrequencyDropdown(): Locator {
    return this.page.getByLabel(/Harvest Report Email Frequency/i);
  }

  get timeZoneDropdown(): Locator {
    return this.page.getByLabel(/Time Zone/i);
  }

  timeZoneOption(value: string): Locator {
    return this.page.getByRole('option', { name: new RegExp(value, 'i') });
  }

  // -- Step 5: Review & Create (documented live-wording note above) --
  get reviewStepHeading(): Locator {
    return this.page.getByRole('heading', { name: /Review (&|and) (Create|Submit)/i });
  }

  summaryCard(stepName: string): Locator {
    return this.page.locator('section, div').filter({ hasText: stepName }).last();
  }

  get submitButton(): Locator {
    return this.page.getByRole('button', { name: /^(Create Ranch|Save Changes)$/ });
  }

  // ==================== Validations ====================

  async isWizardOnStep(stepNumber: number): Promise<boolean> {
    return this.page.getByText(`Step ${stepNumber} of 5`).isVisible();
  }

  async assertWizardOnStep(stepNumber: number): Promise<void> {
    await expect(this.page.getByText(`Step ${stepNumber} of 5`)).toBeVisible();
  }

  async assertNextButtonDisabled(): Promise<void> {
    await expect(this.nextButton).toBeDisabled();
  }

  async assertFieldValidationError(fieldLabel: string): Promise<void> {
    await expect(this.fieldValidationError(fieldLabel)).toBeVisible();
  }

  async assertSuccessToastVisible(): Promise<void> {
    await expect(this.successToast).toBeVisible();
  }

  async assertSubmitButtonLabel(expectedLabel: 'Create Ranch' | 'Save Changes'): Promise<void> {
    await expect(this.page.getByRole('button', { name: expectedLabel, exact: true })).toBeVisible();
  }

  async getFieldValue(locator: Locator): Promise<string> {
    return locator.inputValue();
  }

  // ==================== Actions ====================

  async navigateToRanches(): Promise<void> {
    await this.withHeal(this.ranchesNavLink, (l) => l.click(), 'Ranches Nav Link');
    await this.waitForLoadingToComplete();
  }

  async openCreateRanchWizard(): Promise<void> {
    await this.logInfo('Opening Create Ranch wizard');
    await this.withHeal(this.createNewRanchButton, (l) => l.click(), 'Create New Ranch Button');
  }

  async openEditRanchWizard(ranchName: string): Promise<void> {
    await this.withHeal(this.editRanchButton(ranchName), (l) => l.click(), `Edit Ranch Button: ${ranchName}`);
  }

  async fillBasicInformation(
    ranchName: string,
    fullAddress: string,
    county: string,
    contactPhone: string,
    contactEmail: string,
  ): Promise<void> {
    await this.logInfo('Filling Basic Information step');
    if (ranchName) await this.withHeal(this.ranchNameInput, (l) => l.fill(ranchName), 'Ranch Name Input');
    if (fullAddress) await this.withHeal(this.fullAddressInput, (l) => l.fill(fullAddress), 'Full Address Input');
    if (county) await this.withHeal(this.countyInput, (l) => l.fill(county), 'County Input');
    // Confirmed live 2026-11-03: this field is a libphonenumber-style masked input whose
    // AsYouType formatter re-detects the country from whatever digits are typed, ignoring
    // the Country selector combobox's current selection — EVERY plain national number we
    // tried (regardless of area code) got silently reassigned to a different country's
    // dial code (e.g. "5125551234" became "+51 25559876", Peru). Locator.fill() doesn't
    // drive the masked formatter at all (ends up just "+"). The only reliable sequence
    // found: type the full E.164-style value ("+1" + national number) one keystroke at a
    // time via pressSequentially, which the formatter parses correctly as United States.
    if (contactPhone) {
      const digitsOnly = contactPhone.replace(/\D/g, '');
      const e164 = digitsOnly.startsWith('1') ? `+${digitsOnly}` : `+1${digitsOnly}`;
      await this.withHeal(
        this.contactPhoneInput,
        async (l) => {
          await l.fill('');
          await l.pressSequentially(e164, { delay: 20 });
        },
        'Contact Phone Input',
      );
    }
    if (contactEmail) await this.withHeal(this.contactEmailInput, (l) => l.fill(contactEmail), 'Contact Email Input');
  }

  async fillRanchDetails(propertySize: string, ranchDescription: string, huntableAnimals: string[]): Promise<void> {
    await this.logInfo('Filling Ranch Details step');
    if (propertySize) await this.withHeal(this.propertySizeInput, (l) => l.fill(propertySize), 'Property Size Input');
    if (ranchDescription) await this.withHeal(this.ranchDescriptionInput, (l) => l.fill(ranchDescription), 'Ranch Description Input');
    for (const animal of huntableAnimals) {
      await this.withHeal(this.huntableAnimalOption(animal), (l) => l.click(), `Huntable Animal: ${animal}`);
    }
  }

  async addRoom(roomName: string, beds: number, costPerNight: string, rowIndex = 0): Promise<void> {
    await this.withHeal(this.addRoomButton, (l) => l.click(), 'Add Room Button');
    await this.withHeal(this.roomNameInput(rowIndex), (l) => l.fill(roomName), 'Room Name Input');
    for (let i = 0; i < beds; i++) {
      await this.withHeal(this.bedsStepperIncrement(rowIndex), (l) => l.click(), 'Beds Stepper Increment');
    }
    await this.withHeal(this.costPerNightInput(rowIndex), (l) => l.fill(costPerNight), 'Cost per Night Input');
  }

  async removeRoom(roomName: string): Promise<void> {
    await this.withHeal(this.removeRoomButton(roomName), (l) => l.click(), `Remove Room Button: ${roomName}`);
  }

  async fillInitialSettings(
    turnoverDays: string,
    waiverSigningDeadline: string,
    harvestReportEmailFrequency: string,
    timeZone: string,
  ): Promise<void> {
    await this.logInfo('Filling Initial Settings step');
    if (turnoverDays) {
      await this.withHeal(this.turnoverDaysDropdown, (l) => l.click(), 'Turnover Days Dropdown');
      await this.withHeal(this.turnoverDaysOption(turnoverDays), (l) => l.click(), `Turnover Days Option: ${turnoverDays}`);
    }
    if (waiverSigningDeadline) {
      await this.withHeal(this.waiverSigningDeadlineInput, (l) => l.fill(waiverSigningDeadline), 'Waiver Signing Deadline Input');
    }
    if (harvestReportEmailFrequency) {
      await this.withHeal(this.harvestReportEmailFrequencyDropdown, (l) => l.click(), 'Harvest Report Email Frequency Dropdown');
      await this.withHeal(
        this.page.getByRole('option', { name: harvestReportEmailFrequency }),
        (l) => l.click(),
        `Harvest Report Email Frequency Option: ${harvestReportEmailFrequency}`,
      );
    }
    if (timeZone) {
      await this.withHeal(this.timeZoneDropdown, (l) => l.click(), 'Time Zone Dropdown');
      await this.withHeal(this.timeZoneDropdown, (l) => l.fill(timeZone), 'Time Zone Search Input');
      await this.withHeal(this.timeZoneOption(timeZone), (l) => l.click(), `Time Zone Option: ${timeZone}`);
    }
  }

  async clickNext(): Promise<void> {
    await this.withHeal(this.nextButton, (l) => l.click(), 'Next Button');
  }

  async clickBack(): Promise<void> {
    await this.withHeal(this.backButton, (l) => l.click(), 'Back Button');
  }

  async submitWizard(): Promise<void> {
    await this.logInfo('Submitting Ranch wizard (Review & Create step)');
    await this.withHeal(this.submitButton, (l) => l.click(), 'Wizard Submit Button');
    await this.logSuccess('Ranch wizard submitted');
  }

  async searchRanch(ranchName: string): Promise<void> {
    await this.withHeal(this.searchRanchesInput, (l) => l.fill(ranchName), 'Search Ranches Input');
  }
}
